// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        bool ok;
        try c.transfer(from, caddress, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }
        if (_tos.length > 0) {
            assertTrue(ok);
        }
    }
}
